examples.template:
VStack(alignment: .leading, spacing: theme.spacing.space2) {
    // The heading sits outside the card, as on the web; the card has a red edge and a button at the right of each action.
    Text({{heading}}).monarchTextStyle(.bodyStrong).foregroundStyle(theme.colors.dangerStrong)
    Text({{description}}).monarchTextStyle(.caption).foregroundStyle(theme.colors.textMuted)
    VStack(spacing: 0) {
        HStack(alignment: .center, spacing: theme.spacing.space3) {
            VStack(alignment: .leading, spacing: theme.spacing.space1) {
                Text({{items.0.title}}).monarchTextStyle(.label).fontWeight(.medium)
                Text({{items.0.description}})
                    .monarchTextStyle(.caption)
                    .foregroundStyle(theme.colors.textMuted)
            }
            .frame(maxWidth: .infinity, alignment: .leading)
            MonarchButton({{items.0.action.label}}, variant: {{items.0.action.variant|case}}, size: .sm) {}
                .fixedSize()
        }
        .padding(theme.spacing.space3)
        Divider()
        HStack(alignment: .center, spacing: theme.spacing.space3) {
            VStack(alignment: .leading, spacing: theme.spacing.space1) {
                Text({{items.1.title}}).monarchTextStyle(.label).fontWeight(.medium)
                Text({{items.1.description}})
                    .monarchTextStyle(.caption)
                    .foregroundStyle(theme.colors.textMuted)
            }
            .frame(maxWidth: .infinity, alignment: .leading)
            MonarchButton({{items.1.action.label}}, variant: {{items.1.action.variant|case}}, size: .sm) {
                isConfirming = true
            }
            .fixedSize()
            .disabled(isDeleted)
        }
        .padding(theme.spacing.space3)
    }
    .background(theme.colors.bgSurface)
    .clipShape(RoundedRectangle(cornerRadius: 12, style: .continuous))
    .overlay(RoundedRectangle(cornerRadius: 12, style: .continuous).strokeBorder(theme.colors.borderSubtle))
    .overlay(alignment: .leading) { Rectangle().fill(theme.colors.dangerSolid).frame(width: 3) }
    .clipShape(RoundedRectangle(cornerRadius: 12, style: .continuous))
}
.confirmationDialog("Delete this workspace?", isPresented: $isConfirming, titleVisibility: .visible) {
    Button("Delete workspace", role: .destructive) { isDeleted = true }
    Button("Cancel", role: .cancel) {}
} message: {
    Text("Every project, file and member is deleted. This can't be undone.")
}
.padding(theme.spacing.space4)
.monarchCanvas()
.frame(minHeight: theme.spacing.space24 * 4)

