@Environment(\.monarchTheme) private var theme
@State private var isConfirming = false
@State private var isDeleted = false

examples.setup:
@Environment(\.monarchTheme) private var theme
@State private var isConfirming = false
@State private var isDeleted = false

examples.code:
VStack(alignment: .leading, spacing: theme.spacing.space2) {
    // The heading sits outside the card, as on the web; the card has a red edge and a button at the right of each action.
    Text("Danger zone").monarchTextStyle(.bodyStrong).foregroundStyle(theme.colors.dangerStrong)
    Text("These actions affect everyone in the workspace and cannot be undone.").monarchTextStyle(.caption).foregroundStyle(theme.colors.textMuted)
    VStack(spacing: 0) {
        HStack(alignment: .center, spacing: theme.spacing.space3) {
            VStack(alignment: .leading, spacing: theme.spacing.space1) {
                Text("Transfer ownership").monarchTextStyle(.label).fontWeight(.medium)
                Text("Another member becomes the owner. You stay on as an admin.")
                    .monarchTextStyle(.caption)
                    .foregroundStyle(theme.colors.textMuted)
            }
            .frame(maxWidth: .infinity, alignment: .leading)
            MonarchButton("Transfer ownership", variant: .secondary, size: .sm) {}
                .fixedSize()
        }
        .padding(theme.spacing.space3)
        Divider()
        HStack(alignment: .center, spacing: theme.spacing.space3) {
            VStack(alignment: .leading, spacing: theme.spacing.space1) {
                Text("Delete this workspace").monarchTextStyle(.label).fontWeight(.medium)
                Text("Projects, tasks and files are deleted for everyone.")
                    .monarchTextStyle(.caption)
                    .foregroundStyle(theme.colors.textMuted)
            }
            .frame(maxWidth: .infinity, alignment: .leading)
            MonarchButton("Delete workspace", variant: .danger, size: .sm) {
                isConfirming = true
            }
            .fixedSize()
            .disabled(isDeleted)
        }
        .padding(theme.spacing.space3)
    }
    .background(theme.colors.bgSurface)
    .clipShape(RoundedRectangle(cornerRadius: 12, style: .continuous))
    .overlay(RoundedRectangle(cornerRadius: 12, style: .continuous).strokeBorder(theme.colors.borderSubtle))
    .overlay(alignment: .leading) { Rectangle().fill(theme.colors.dangerSolid).frame(width: 3) }
    .clipShape(RoundedRectangle(cornerRadius: 12, style: .continuous))
}
.confirmationDialog("Delete this workspace?", isPresented: $isConfirming, titleVisibility: .visible) {
    Button("Delete workspace", role: .destructive) { isDeleted = true }
    Button("Cancel", role: .cancel) {}
} message: {
    Text("Every project, file and member is deleted. This can't be undone.")
}
.padding(theme.spacing.space4)
.monarchCanvas()
.frame(minHeight: theme.spacing.space24 * 4)

MonarchSectionCard("Danger zone", description: "Only workspace owners can use these actions.", tone: .danger) {
    VStack(alignment: .leading, spacing: theme.spacing.space1) {
        Text("Leave workspace")
            .monarchTextStyle(.bodyStrong)
            .accessibilityAddTraits(.isHeader)
        Text("You lose access to its projects until someone invites you again.")
            .monarchTextStyle(.caption)
            .foregroundStyle(theme.colors.textMuted)
        MonarchButton("Leave workspace", variant: .danger, size: .sm) { isConfirming = true }
    }
}
.alert(
    "Leave this workspace?",
    isPresented: $isConfirming,
    actions: {
        Button("Leave", role: .destructive) {}
        Button("Cancel", role: .cancel) {}
    },
    message: {
        Text("You lose access to its projects.")
    }
)
